  "vulnerabilities": [
    {
      "dependency": {
        "name": "idna",
        "version": "3.6"
      },
      "id": "GHSA-65pc-fj4g-8rjx",
      "display_id": "GHSA-65pc-fj4g-8rjx",
      "aliases": [
        "CVE-2026-45409",
        "PYSEC-2026-215"
      ],
      "summary": "Internationalized Domain Names in Applications (IDNA): Specially crafted inputs to idna.encode() can bypass CVE-2024-3651 fix",
      "description": "This is the same issue as CVE-2024-3651, however the original remediation in 2024 was not a complete fix. Payloads such as `\"\\u0660\" * N` or `\"\\u30fb\" * N + \"\\u6f22\"` utilize the `valid_contexto` function prior to length rejection, and for high values of `N` will take a long time to process.\n\n### Impact\nA specially crafted argument to the `idna.encode()` function could consume significant resources. This may lead to a denial-of-service.\n\n### Patches\nStarting in version 3.14, the function rejects long inputs as soon as practicable prior to any further processing to minimize resource consumption. In version 3.15, this approach was extended to lesser used alternate functions (i.e. per-label conversions and codec support).\n\n### Workarounds\nDomain names cannot exceed 253 characters in length, if this length limit is enforced prior to passing the domain to the `idna.encode()` function it should no longer consume significant resources. This is triggered by arbitrarily large inputs that would not occur in normal usage, but may be passed to the library assuming there is no preliminary input validation by the higher-level application.",
      "link": "https://nvd.nist.gov/vuln/detail/CVE-2026-45409",
      "fix_versions": [
        "3.15"
      ],
      "published": "2026-05-19T14:34:32Z",
      "modified": "2026-09-10T03:50:45.700124422Z"
    },
    {
      "dependency": {
        "name": "idna",
        "version": "3.6"
      },
      "id": "GHSA-jjg7-2v4v-x38h",
      "display_id": "GHSA-jjg7-2v4v-x38h",
      "aliases": [
        "CVE-2024-3651",
        "PYSEC-2024-60"
      ],
      "summary": "Internationalized Domain Names in Applications (IDNA) vulnerable to denial of service from specially crafted inputs to idna.encode",
      "description": "### Impact\nA specially crafted argument to the `idna.encode()` function could consume significant resources. This may lead to a denial-of-service.\n\n### Patches\nThe function has been refined to reject such strings without the associated resource consumption in version 3.7.\n\n### Workarounds\nDomain names cannot exceed 253 characters in length, if this length limit is enforced prior to passing the domain to the `idna.encode()` function it should no longer consume significant resources. This is triggered by arbitrarily large inputs that would not occur in normal usage, but may be passed to the library assuming there is no preliminary input validation by the higher-level application.\n\n### References\n* https://huntr.com/bounties/93d78d07-d791-4b39-a845-cbfabc44aadb",
      "link": "https://nvd.nist.gov/vuln/detail/CVE-2024-3651",
      "fix_versions": [
        "3.7"
      ],
      "published": "2024-04-11T21:32:40Z",
      "modified": "2026-09-10T03:50:12.774088619Z"
    },
    {
      "dependency": {
        "name": "idna",
        "version": "3.6"
      },
      "id": "PYSEC-2024-60",
      "display_id": "PYSEC-2024-60",
      "aliases": [
        "CVE-2024-3651",
        "GHSA-jjg7-2v4v-x38h"
      ],
      "summary": null,
      "description": "A vulnerability was identified in the kjd/idna library, specifically within the `idna.encode()` function, affecting version 3.6. The issue arises from the function's handling of crafted input strings, which can lead to quadratic complexity and consequently, a denial of service condition. This vulnerability is triggered by a crafted input that causes the `idna.encode()` function to process the input with considerable computational load, significantly increasing the processing time in a quadratic manner relative to the input size.",
      "link": "https://github.com/advisories/GHSA-jjg7-2v4v-x38h",
      "fix_versions": [
        "3.7"
      ],
      "published": "2024-07-07T18:15:00Z",
      "modified": "2026-06-10T17:01:21.102419358Z"
    },
    {
      "dependency": {
        "name": "idna",
        "version": "3.6"
      },
      "id": "PYSEC-2026-215",
      "display_id": "PYSEC-2026-215",
      "aliases": [
        "CVE-2026-45409",
        "GHSA-65pc-fj4g-8rjx"
      ],
      "summary": null,
      "description": "Internationalized Domain Names in Applications (IDNA) for Python provides support for Internationalized Domain Names in Applications (IDNA) and Unicode IDNA Compatibility Processing. In versions prior to 3.15, payloads such as `\"\\u0660\" * N` or `\"\\u30fb\" * N + \"\\u6f22\"` utilize the `valid_contexto` function prior to length rejection, and for high values of `N` will take a long time to process. This is the same issue as CVE-2024-3651, however the original remediation in 2024 was not a complete fix. A specially crafted argument to the `idna.encode()` function could consume significant resources. This may lead to a denial-of-service. Starting in version 3.14, the function rejects long inputs as soon as practicable prior to any further processing to minimize resource consumption. In version 3.15, this approach was extended to lesser used alternate functions (i.e. per-label conversions and codec support). A workaround is available. Domain names cannot exceed 253 characters in length. If this length limit is enforced prior to passing the domain to the `idna.encode()` function, it should no longer consume significant resources. This is triggered by arbitrarily large inputs that would not occur in normal usage, but may be passed to the library assuming there is no preliminary input validation by the higher-level application.",
      "link": "https://github.com/kjd/idna/security/advisories/GHSA-65pc-fj4g-8rjx",
      "fix_versions": [
        "3.15"
      ],
      "published": "2026-06-05T23:16:43.343Z",
      "modified": "2026-06-16T16:15:04.639265054Z"
    }
  ],
  "adverse_statuses": []
}

